<script lang="ts">
 // Svelte adaptation of Shadcnblocks user-profile1 (free registry block).
 // Source: https://www.shadcnblocks.com/block/user-profile1
 // License: https://www.shadcnblocks.com/license
 import * as Card from '$lib/components/ui/card';
 import {Button} from '$lib/components/ui/button';
 import {MapPin,Globe,ExternalLink,Film,Heart} from '@lucide/svelte';
 let {data,user,busy=false,followed=false,onFollow}:{data:any;user:any;busy?:boolean;followed?:boolean;onFollow:()=>void}=$props();
 const channel=$derived(data.channel || data);
 const videos=$derived(data.videos || []);
 const featured=$derived(videos.find((video:any)=>video.id===channel.featured_video_id));
 const releases=$derived(videos.filter((video:any)=>video.id!==featured?.id));
 const safeLink=(value:string)=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:undefined;}catch{return undefined;}};
</script>
<section class="public-profile">
 {#if channel.banner_url}<div class="profile-banner"><img src={channel.banner_url} alt=""/></div>{/if}
 <div class="profile-layout"><Card.Root class="profile-identity text-center"><Card.Header class="items-center justify-items-center gap-4 pb-0"><div class="profile-avatar">{#if channel.avatar_url}<img src={channel.avatar_url} alt={channel.name || channel.handle}/>{:else}<span>{(channel.name || channel.handle || 'V').split(' ').map((part:string)=>part[0]).slice(0,2).join('').toUpperCase()}</span>{/if}</div><div class="space-y-1"><h1 class="text-xl font-semibold">{channel.name || channel.handle}</h1><p class="text-sm text-muted-foreground">@{channel.handle}</p></div></Card.Header><Card.Content class="space-y-4 pt-6"><p class="text-sm text-muted-foreground whitespace-pre-wrap">{channel.bio || channel.description || 'This creator has not added a bio yet.'}</p>{#if channel.location}<p class="flex items-center justify-center gap-1.5 text-sm text-muted-foreground"><MapPin class="size-3.5"/>{channel.location}</p>{/if}{#if safeLink(channel.website)}<a class="profile-link" href={safeLink(channel.website)} target="_blank" rel="noopener noreferrer"><Globe class="size-3.5"/>{new URL(channel.website).hostname}<ExternalLink class="size-3"/></a>{/if}{#each channel.social_links || [] as link}{#if safeLink(link.url)}<a class="profile-link" href={safeLink(link.url)} target="_blank" rel="noopener noreferrer">{link.label}<ExternalLink class="size-3"/></a>{/if}{/each}<dl class="profile-counts">{#if typeof channel.followers==='number'}<div><dt>Followers</dt><dd>{channel.followers.toLocaleString()}</dd></div>{/if}{#if typeof channel.public_video_count==='number'}<div><dt>Public videos</dt><dd>{channel.public_video_count.toLocaleString()}</dd></div>{/if}{#if typeof channel.public_views==='number'}<div><dt>Public views</dt><dd>{channel.public_views.toLocaleString()}</dd></div>{/if}</dl>{#if channel.joined_at}<p class="text-xs text-muted-foreground">Joined {new Date(channel.joined_at).toLocaleDateString(undefined,{month:'long',year:'numeric'})}</p>{/if}</Card.Content><Card.Footer class="justify-center gap-2">{#if user?.channel_id===channel.id}<Button href="/profile" variant="outline" class="flex-1">Edit profile</Button><Button href="/studio/channel" class="flex-1">Manage videos</Button>{:else}<Button variant="outline" class="flex-1" disabled={busy||followed} onclick={onFollow}><Heart class="size-4"/>{followed?'Following':'Follow for free'}</Button>{/if}</Card.Footer></Card.Root>
 <div class="profile-videos">{#if featured}<section class="featured-video"><h2>Featured video</h2><a class="video-tile" href={`/watch/${featured.id}`}><div class="video-image">{#if featured.thumbnail_url}<img src={featured.thumbnail_url} alt=""/>{:else}<Film class="size-8"/>{/if}<span class="profile-video-access">{featured.audience==='members'?'Premium':'Free'}</span></div><h3>{featured.title}</h3><p class="subtle">{featured.views.toLocaleString()} views</p></a></section>{/if}{#if releases.length || !featured}<div class="section-heading"><h2>Videos</h2><span class="text-sm text-muted-foreground">Public releases</span></div>{/if}{#if releases.length}<div class="video-grid">{#each releases as video}<a class="video-tile" href={`/watch/${video.id}`}><div class="video-image">{#if video.thumbnail_url}<img src={video.thumbnail_url} alt="" loading="lazy"/>{:else}<Film class="size-8"/>{/if}<span class="profile-video-access">{video.audience==='members'?'Premium':'Free'}</span></div><h3>{video.title}</h3>{#if typeof video.views==='number'}<p class="subtle">{video.views.toLocaleString()} views</p>{/if}</a>{/each}</div>{:else if !featured}<div class="cloud-empty compact"><Film class="size-8"/><h2>No public videos yet</h2><p>Published public videos from this creator will appear here.</p></div>{/if}</div></div>
</section>

<style>.featured-video{margin-bottom:32px}.featured-video h2{font-size:16px;font-weight:600;margin:0 0 16px}.featured-video .video-tile{display:block}.featured-video .video-image{aspect-ratio:16/9}</style>
